cypress_script:
describe('Product Catalogue with Sorting', () => {
  it('should allow user to sort products by name (A to Z)', () => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="product-sort-container"]').select('az');
    cy.url().should('include', '/inventory.html');
    cy.get('[data-test="item-0-title-link"]').should('be.visible');
  });

  it('should show no products when sorting fails', () => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="product-sort-container"]').select('invalid_option');
    cy.url().should('include', '/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Catalogue with Sorting', () => {
  test('should allow user to sort products by name (A to Z)', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.selectOption('[data-test="product-sort-container"]', 'az');
    await expect(page).toHaveURL(/.*inventory.html/);
    await expect(page.locator('[data-test="item-0-title-link"]')).toBeVisible();
  });

  test('should show no products when sorting fails', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.selectOption('[data-test="product-sort-container"]', 'invalid_option');
    await expect(page).toHaveURL(/.*inventory.html/);
  });
});
